import json
from remote import call,ROOT
files={"overlay/gamecam_io_overlay.py":"","overlay/io_import_overlay.py":"","overlay/runtime_io.py":"","overlay/sitecustomize.py":"","sitecustomize.py":"","tests/full_buffer_tmpfs_stress.py":"","tests/file_support.py":""}
code=r'''
import os,pathlib,shutil,json,hashlib,base64,subprocess,time
old=pathlib.Path('/root/rivermind-data/DROID_W_TASK004C_B_IO_COMPAT_20261124_R2_READY');r=pathlib.Path('/root/rivermind-data/DROID_W_TASK004C_B_IO_COMPAT_20261125_R3_OFFLINE')
assert not r.exists();r.mkdir(mode=0o700)
def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(8*1024**2),b''):h.update(b)
 return h.hexdigest()
links=[]
def owned_copy(src,dst):
 if '.git' in src.parts:shutil.copy2(src,dst)
 else:
  before=sha(src);st=src.stat();os.link(src,dst);assert sha(dst)==before
  links.append({'source':str(src),'new':str(dst),'sha256':before,'source_inode':st.st_ino,'read_only_reuse':True,'link_count_metadata_changed':True})
 return str(dst)
shutil.copytree(old/'source_candidate',r/'source_candidate',copy_function=lambda a,b:owned_copy(pathlib.Path(a),pathlib.Path(b)),symlinks=True)
shutil.copytree(old/'C0',r/'C0',copy_function=lambda a,b:owned_copy(pathlib.Path(a),pathlib.Path(b)))
for name in ('authorization','configs','operational','tests'):
 shutil.copytree(old/name,r/name,ignore=shutil.ignore_patterns('__pycache__','*.pyc'))
for name in ('evidence','attempts','artifacts','overlay'):(r/name).mkdir()
for name in ('CPU_FINAL_ACCEPTANCE.json','CPU_STAGE_RELEASE.json','FILE_BACKED_CPU_VALIDATION.json','IO_CPU_TEST_REPORT.json'):
 shutil.copy2(old/'evidence'/name,r/'evidence'/name)
# Reuse completed capture/Short80 receipts verbatim. These are not new GPU runs.
for mode in ('capture','restore_check','record_S1','replay_D0_S1','record_S0','replay_D1_S0'):
 src=old/'attempts'/mode
 shutil.copytree(src,r/'attempts'/mode,copy_function=shutil.copy2,ignore=shutil.ignore_patterns('shared_cpu','*.rrd','native','__pycache__'))
for rel,b in FILES.items():
 p=r/rel;p.parent.mkdir(exist_ok=True,parents=True);p.write_bytes(base64.b64decode(b))
(r/'tests/__init__.py').touch(exist_ok=True)
manifest=json.loads((old/'overlay/OVERLAY_MANIFEST.json').read_text())
manifest.update(schema='GAMECAM_RUNTIME_IO_RECOVERY_V3',scope='OUTPUT_LIFECYCLE_LOCAL_HUB_LOSSLESS_VIDEO_TMPFS_FILE_MMAP')
manifest['files']={rel:sha(r/rel) for rel in ('overlay/gamecam_io_overlay.py','overlay/io_import_overlay.py','overlay/runtime_io.py','overlay/sitecustomize.py','sitecustomize.py','tests/test_io_lifecycle.py')}
(r/'overlay/OVERLAY_MANIFEST.json').write_text(json.dumps(manifest,indent=2))
(r/'evidence/IMMUTABLE_READONLY_LINK_REUSE.json').write_text(json.dumps({'files':links,'file_contents_modified':False,'checkpoint_recaptured':False,'source_file_inodes_retained':True,'metadata_note':'Only hard-link counts/ctime change; all payload SHA values unchanged. C0 and candidate are read-only inputs; attempts allocate independent fresh storages.'},indent=2))
(r/'evidence/R3_RECOVERY_SCOPE.json').write_text(json.dumps({'reason':'R2 B1 failed in Filler feature extractor torch.hub network lookup; frontend and Final BA preserved','reused_completed_stages_from':str(old),'source_commit':'5d357c1d3079de134dd8b41a20a00632da37f0b0','C0_SHA256':'18ab8ceff97339eded44af2e716cb6c43c8d5679a212a8183f84751fce9fad92','shared_arena':'same FileArena/reducer on existing 24GiB tmpfs; no mount changes','video_output':'lossless np.savez_compressed; same arrays/dtypes/values','gpu_runs_launched':0},indent=2))
release=json.loads((r/'evidence/CPU_STAGE_RELEASE.json').read_text());assert all(sha(r/n)==v for n,v in release['candidate_pins'].items())
assert not subprocess.check_output(['git','-C',str(r/'source_candidate'),'status','--porcelain','--untracked-files=all'],text=True).strip()
assert all(sha(pathlib.Path(x['source']))==x['sha256'] for x in links)
print(json.dumps({'workspace':str(r),'linked_immutable_files':len(links),'all_payload_hashes_match':True,'GPU_runs':0,'free_disk_bytes':shutil.disk_usage(r).free,'shm':dict(zip(('total','used','free'),shutil.disk_usage('/dev/shm'))),'manifest':manifest}))
'''.replace('FILES',repr(files))
a=call('R3_OFFLINE_RECOVERY_PREPARATION_01',code,timeout=480)
(ROOT/'evidence/R3_OFFLINE_RECOVERY_PREPARATION.json').write_text(json.dumps(a,indent=2))
print(json.dumps({k:v for k,v in a.items() if k!='manifest'},indent=2))
